import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Plus, Edit, Trash2, Upload } from 'lucide-react';
import { customerClicksService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';
import { CustomerClick } from '@/services/mockData';
import { format } from 'date-fns';

// Extended interface for the form data
interface CustomerClickFormData {
  image: string;
  date: string;
  functionName: string;
  customerName: string;
  title: string;
  boyName: string;
  girlName: string;
  hallId: string;
}

// Extended CustomerClick interface for the mock data
interface ExtendedCustomerClick extends CustomerClick {
  image?: string;
  boyName?: string;
  girlName?: string;
}

const CustomerClicks = () => {
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [editingClick, setEditingClick] = useState<ExtendedCustomerClick | null>(null);
  const [newClick, setNewClick] = useState<CustomerClickFormData>({
    image: '',
    date: '',
    functionName: '',
    customerName: '',
    title: '',
    boyName: '',
    girlName: '',
    hallId: '1'
  });
  const [selectedImage, setSelectedImage] = useState<File | null>(null);

  // Use service hook for data fetching
  const {
    data: customerClicks,
    loading: clicksLoading,
    error: clicksError,
    refresh: refreshClicks
  } = useService(() => Promise.resolve(customerClicksService.getAll()));

  const handleSave = async () => {
    try {
      if (editingClick) {
        // For update, we need to cast to any to include the image property
        await customerClicksService.update(editingClick.id, {
          ...newClick,
          image: selectedImage ? URL.createObjectURL(selectedImage) : newClick.image
        } as any);
      } else {
        // For create, we need to cast to any to include the image property
        await customerClicksService.create({
          ...newClick,
          image: selectedImage ? URL.createObjectURL(selectedImage) : 'photo-1519167758481-83f29c8b5bd0'
        } as any);
      }
      
      refreshClicks();
      setShowAddDialog(false);
      setEditingClick(null);
      setNewClick({
        image: '',
        date: '',
        functionName: '',
        customerName: '',
        title: '',
        boyName: '',
        girlName: '',
        hallId: '1'
      });
      setSelectedImage(null);
    } catch (error) {
      console.error('Error saving customer click:', error);
    }
  };

  const handleEdit = (click: ExtendedCustomerClick) => {
    setEditingClick(click);
    setNewClick({
      image: click.image || '',
      date: click.eventDate || '',
      functionName: click.eventType || '',
      customerName: click.customerName || '',
      title: click.eventType || '', // Use eventType as title for existing records
      boyName: click.boyName || '',
      girlName: click.girlName || '',
      hallId: click.hallId || '1'
    });
    setShowAddDialog(true);
  };

  const handleDelete = async (id: string) => {
    try {
      await customerClicksService.delete(id);
      refreshClicks();
    } catch (error) {
      console.error('Error deleting customer click:', error);
    }
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      setSelectedImage(file);
    }
  };

  const openAddDialog = () => {
    setEditingClick(null);
    setNewClick({
      image: '',
      date: '',
      functionName: '',
      customerName: '',
      title: '',
      boyName: '',
      girlName: '',
      hallId: '1'
    });
    setSelectedImage(null);
    setShowAddDialog(true);
  };

  // Show loading state
  if (clicksLoading) {
    return <div>Loading customer clicks...</div>;
  }

  // Show error state
  if (clicksError) {
    return <div>Error loading customer clicks: {clicksError}</div>;
  }

  const clicks = customerClicks || [];

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-3xl font-bold">Customer Clicks</h1>
            <p className="text-gray-600">Manage customer event images and memories</p>
          </div>
          <Button onClick={openAddDialog}>
            <Plus className="h-4 w-4 mr-2" />
            Add Customer Click
          </Button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {clicks.map((click) => {
            const extendedClick = click as ExtendedCustomerClick;
            return (
              <Card key={click.id} className="overflow-hidden">
                <div className="aspect-[4/3] relative">
                  <img
                    src={extendedClick.image?.startsWith('blob:') ? extendedClick.image : `https://images.unsplash.com/${extendedClick.image}?auto=format&fit=crop&w=400&q=80`}
                    alt={click.eventType}
                    className="w-full h-full object-cover"
                  />
                </div>
                
                <CardHeader>
                  <CardTitle className="text-lg">{click.eventType}</CardTitle>
                </CardHeader>
                
                <CardContent className="space-y-2">
                  <p className="text-sm text-gray-600">{click.customerName}</p>
                  {extendedClick.boyName && <p className="text-sm">Boy: {extendedClick.boyName}</p>}
                  {extendedClick.girlName && <p className="text-sm">Girl: {extendedClick.girlName}</p>}
                  <Badge variant="secondary" className="text-xs">
                    {format(new Date(click.eventDate), 'MMM dd, yyyy')}
                  </Badge>
                  
                  <div className="flex gap-2 pt-2">
                    <Button size="sm" variant="outline" onClick={() => handleEdit(extendedClick)}>
                      <Edit className="h-4 w-4" />
                    </Button>
                    <Button size="sm" variant="outline" onClick={() => handleDelete(click.id)}>
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>

        <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>{editingClick ? 'Edit' : 'Add'} Customer Click</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label>Image</Label>
                <div className="space-y-2">
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="hidden"
                    id="image-upload"
                  />
                  <label htmlFor="image-upload">
                    <Button asChild variant="outline" className="w-full">
                      <span className="cursor-pointer">
                        <Upload className="h-4 w-4 mr-2" />
                        Upload Image
                      </span>
                    </Button>
                  </label>
                  {(selectedImage || newClick.image) && (
                    <div className="aspect-video relative border rounded">
                      <img
                        src={selectedImage ? URL.createObjectURL(selectedImage) : 
                          newClick.image.startsWith('blob:') ? newClick.image : 
                          `https://images.unsplash.com/${newClick.image}?auto=format&fit=crop&w=400&q=80`}
                        alt="Preview"
                        className="w-full h-full object-cover rounded"
                      />
                    </div>
                  )}
                </div>
              </div>
              
              <div>
                <Label htmlFor="date">Event Date</Label>
                <Input
                  id="date"
                  type="date"
                  value={newClick.date}
                  onChange={(e) => setNewClick(prev => ({ ...prev, date: e.target.value }))}
                />
              </div>
              
              <div>
                <Label htmlFor="title">Title</Label>
                <Input
                  id="title"
                  value={newClick.title}
                  onChange={(e) => setNewClick(prev => ({ ...prev, title: e.target.value, functionName: e.target.value }))}
                  placeholder="e.g., Wedding Reception"
                />
              </div>
              
              <div>
                <Label htmlFor="customerName">Customer Name</Label>
                <Input
                  id="customerName"
                  value={newClick.customerName}
                  onChange={(e) => setNewClick(prev => ({ ...prev, customerName: e.target.value }))}
                  placeholder="Customer or family name"
                />
              </div>
              
              <div>
                <Label htmlFor="boyName">Boy Name</Label>
                <Input
                  id="boyName"
                  value={newClick.boyName}
                  onChange={(e) => setNewClick(prev => ({ ...prev, boyName: e.target.value }))}
                  placeholder="Groom name (optional)"
                />
              </div>
              
              <div>
                <Label htmlFor="girlName">Girl Name</Label>
                <Input
                  id="girlName"
                  value={newClick.girlName}
                  onChange={(e) => setNewClick(prev => ({ ...prev, girlName: e.target.value }))}
                  placeholder="Bride name (optional)"
                />
              </div>
              
              <Button onClick={handleSave} className="w-full">
                {editingClick ? 'Update' : 'Add'} Customer Click
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  );
};

export default CustomerClicks;
