import React from 'react';
import { Star } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { reviewService, organizationService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';

export function PublicReviewsSection() {
  // Get current organization using service hook
  const {
    data: organization,
    loading: orgLoading,
    error: orgError
  } = useService(() => Promise.resolve(organizationService.getCurrentOrganization()));

  // Get reviews using service hook
  const {
    data: reviews,
    loading: reviewsLoading,
    error: reviewsError,
    execute: executeReviews
  } = useService(() => {
    if (organization?.id) {
      return Promise.resolve(reviewService.getReviewsByOrganization(organization.id));
    }
    return Promise.resolve([]);
  }, {
    immediate: false
  });

  // Execute reviews fetch when organization is loaded
  React.useEffect(() => {
    if (organization?.id) {
      executeReviews();
    }
  }, [organization?.id, executeReviews]);

  // Loading state
  if (orgLoading || reviewsLoading) {
    return (
      <section className="py-12 bg-gray-50">
        <div className="container mx-auto px-4">
          <div className="animate-pulse">
            <div className="h-8 bg-gray-200 rounded w-1/4 mb-8"></div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[...Array(3)].map((_, i) => (
                <div key={i} className="h-48 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </div>
      </section>
    );
  }

  // Error state
  if (orgError || reviewsError || !organization) {
    return null;
  }

  // If no reviews, show default testimonials
  const displayReviews = reviews && reviews.length > 0 ? reviews.slice(0, 3) : [
    {
      id: '1',
      customerName: 'Sarah & John',
      rating: 5,
      comment: 'Amazing venue and excellent service. Our wedding was perfect!'
    },
    {
      id: '2',
      customerName: 'Maria & David',
      rating: 5,
      comment: 'Beautiful location and professional staff. Highly recommended!'
    },
    {
      id: '3',
      customerName: 'Lisa & Michael',
      rating: 5,
      comment: 'The best wedding venue we could have chosen. Everything was perfect!'
    }
  ];

  return (
    <section className="py-12 bg-gray-50">
      <div className="container mx-auto px-4">
        <h2 className="text-3xl font-bold text-center mb-8">What Our Customers Say</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {displayReviews.map((review) => (
            <Card key={review.id}>
              <CardHeader>
                <div className="flex items-center">
                  {[...Array(5)].map((_, i) => (
                    <Star key={i} className="h-5 w-5 fill-yellow-400 text-yellow-400" />
                  ))}
                </div>
              </CardHeader>
              <CardContent>
                <p className="text-gray-600 mb-4">
                  "{review.comment}"
                </p>
                <p className="font-semibold">- {review.customerName}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}
