
import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { Plus, Edit, Trash2, User } from 'lucide-react';
import { User as UserType } from '@/types';

const Users = () => {
  const [users] = useState<UserType[]>([
    {
      id: '1',
      name: 'Admin User',
      email: 'admin@royalweddings.com',
      organizationId: '1',
      accessibleHalls: ['1', '2', '3'],
      role: 'admin'
    },
    {
      id: '2',
      name: 'Hall Manager',
      email: 'manager@royalweddings.com',
      organizationId: '1',
      accessibleHalls: ['1', '2'],
      role: 'manager'
    }
  ]);

  const [newUser, setNewUser] = useState({
    name: '',
    email: '',
    role: 'manager' as 'admin' | 'manager',
    accessibleHalls: [] as string[]
  });

  const availableHalls = [
    { id: '1', name: 'Crystal Palace Hall' },
    { id: '2', name: 'Golden Dreams Hall' },
    { id: '3', name: 'Elegant Manor' }
  ];

  const handleAddUser = () => {
    console.log('Adding new user:', newUser);
    setNewUser({ name: '', email: '', role: 'manager', accessibleHalls: [] });
  };

  const handleHallAccess = (hallId: string, checked: boolean) => {
    if (checked) {
      setNewUser({ ...newUser, accessibleHalls: [...newUser.accessibleHalls, hallId] });
    } else {
      setNewUser({ ...newUser, accessibleHalls: newUser.accessibleHalls.filter(id => id !== hallId) });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Users Management</h1>
          <p className="text-gray-600">Manage user access and permissions</p>
        </div>
        <Dialog>
          <DialogTrigger asChild>
            <Button>
              <Plus className="h-4 w-4 mr-2" />
              Add User
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Add New User</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label htmlFor="name">Name</Label>
                <Input
                  id="name"
                  value={newUser.name}
                  onChange={(e) => setNewUser({ ...newUser, name: e.target.value })}
                />
              </div>
              <div>
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={newUser.email}
                  onChange={(e) => setNewUser({ ...newUser, email: e.target.value })}
                />
              </div>
              <div>
                <Label>Accessible Halls</Label>
                <div className="space-y-2 mt-2">
                  {availableHalls.map((hall) => (
                    <div key={hall.id} className="flex items-center space-x-2">
                      <Checkbox
                        id={hall.id}
                        checked={newUser.accessibleHalls.includes(hall.id)}
                        onCheckedChange={(checked) => handleHallAccess(hall.id, checked as boolean)}
                      />
                      <Label htmlFor={hall.id}>{hall.name}</Label>
                    </div>
                  ))}
                </div>
              </div>
              <Button onClick={handleAddUser} className="w-full">
                Add User
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {users.map((user) => (
          <Card key={user.id}>
            <CardHeader>
              <div className="flex items-center space-x-2">
                <User className="h-6 w-6" />
                <div>
                  <CardTitle>{user.name}</CardTitle>
                  <CardDescription>{user.email}</CardDescription>
                </div>
              </div>
            </CardHeader>
            
            <CardContent>
              <div className="space-y-3">
                <div>
                  <Badge variant={user.role === 'admin' ? 'default' : 'secondary'}>
                    {user.role}
                  </Badge>
                </div>
                
                <div>
                  <p className="text-sm text-gray-600">Accessible Halls: {user.accessibleHalls.length}</p>
                </div>
                
                <div className="flex gap-2">
                  <Button variant="outline" size="sm">
                    <Edit className="h-4 w-4 mr-1" />
                    Edit
                  </Button>
                  <Button variant="destructive" size="sm">
                    <Trash2 className="h-4 w-4 mr-1" />
                    Delete
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
};

export default Users;
