import React from 'react';
import { Button } from '@/components/ui/button';
import { organizationService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';
import { useNavigate } from 'react-router-dom';

export function TopNavigation() {
  const navigate = useNavigate();
  
  // Get current organization using service hook
  const {
    data: organization,
    loading: orgLoading,
    error: orgError
  } = useService(() => organizationService.getCurrentOrganization());

  const handleLogin = () => {
    navigate('/login');
  };

  // Loading state
  if (orgLoading) {
    return (
      <nav className="bg-white shadow-sm border-b">
        <div className="container mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center">
              <div className="h-8 w-8 mr-3 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-6 w-32 bg-gray-200 rounded animate-pulse"></div>
            </div>
            <Button disabled>Login</Button>
          </div>
        </div>
      </nav>
    );
  }

  // Error state
  if (orgError || !organization) {
    return (
      <nav className="bg-white shadow-sm border-b">
        <div className="container mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center">
              <h1 className="text-xl font-bold text-gray-900">Organization</h1>
            </div>
            <Button onClick={handleLogin}>Login</Button>
          </div>
        </div>
      </nav>
    );
  }

  return (
    <nav className="bg-white shadow-sm border-b">
      <div className="container mx-auto px-4">
        <div className="flex justify-between items-center h-16">
          <div className="flex items-center">
            <img
              src={organization.logo}
              alt={organization.name}
              className="h-8 w-8 mr-3"
            />
            <h1 className="text-xl font-bold text-gray-900">{organization.name}</h1>
          </div>
          <Button onClick={handleLogin}>
            Login
          </Button>
        </div>
      </div>
    </nav>
  );
}
