import React, { useState } from 'react';
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { MapPin, Users, Clock, Building } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { hallService } from '@/services/ServiceFactory';
import { useService } from '@/hooks/useService';
import { PublicHallCalendar } from './PublicHallCalendar';

export function PublicHallsSection() {
  const navigate = useNavigate();
  const {
    data: halls,
    loading: hallsLoading,
    error: hallsError
  } = useService(() => Promise.resolve(hallService.getAllHalls()));
  const [selectedDates, setSelectedDates] = useState<Record<string, Date | null>>({});

  const handleDateSelect = (hallId: string, date: Date | null) => {
    setSelectedDates(prev => ({
      ...prev,
      [hallId]: date
    }));
  };

  const handleBookingClick = (hallId: string) => {
    const selectedDate = selectedDates[hallId];
    if (selectedDate) {
      const params = new URLSearchParams({
        date: selectedDate.toISOString().split('T')[0]
      });
      navigate(`/booking/${hallId}?${params.toString()}`);
    }
  };

  if (hallsLoading) {
    return (
      <section className="py-12 bg-white">
        <div className="container mx-auto px-4">
          <div className="animate-pulse">
            <div className="h-8 bg-gray-200 rounded w-1/4 mb-8"></div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {[...Array(3)].map((_, i) => (
                <div key={i} className="h-64 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </div>
      </section>
    );
  }

  if (hallsError || !halls) {
    return null;
  }

  return (
    <section className="py-16 bg-background">
      <div className="container mx-auto px-4">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold mb-4">Our Wedding Halls</h2>
          <p className="text-gray-600 max-w-2xl mx-auto">
            Discover our beautiful venues perfect for your special day. Each hall is designed 
            to create magical moments and unforgettable memories.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {halls.map((hall) => (
            <Card key={hall.id} className="overflow-hidden hover:shadow-lg transition-shadow">
              <div className="relative h-48">
                <img
                  src={hall.gallery[0] || 'https://images.unsplash.com/photo-1519225421980-715cb0215aed?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=2070&q=80'}
                  alt={hall.name}
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-black/20"></div>
              </div>
              <CardHeader>
                <CardTitle className="text-xl">{hall.name}</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  <div className="flex items-center text-gray-600">
                    <Users className="h-4 w-4 mr-2" />
                    <span>Capacity: {hall.capacity} guests</span>
                  </div>
                  <div className="flex items-center text-gray-600">
                    <MapPin className="h-4 w-4 mr-2" />
                    <span>{hall.location}</span>
                  </div>
                  <div className="flex items-center text-gray-600">
                    <Building className="h-4 w-4 mr-2" />
                    <span>₹{hall.rateCard.fullDayRate.toLocaleString()}/day</span>
                  </div>
                </div>
                <Button className="w-full mt-4">
                  View Details
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}
