export interface EnvironmentConfig {
  useMockData: boolean;
  apiBaseUrl: string;
  environment: string;
  debug: boolean;
}

const getEnvironmentConfig = (): EnvironmentConfig => {
  const env = import.meta.env.MODE || 'development';
  
  switch (env) {
    case 'development':
      return {
        useMockData: import.meta.env.VITE_USE_MOCK_DATA === 'true' || true,
        apiBaseUrl: import.meta.env.VITE_API_BASE_URL || 'https://momantza.com/',
        environment: 'development',
        debug: true
      };
    
    case 'production':
      return {
        useMockData: import.meta.env.VITE_USE_MOCK_DATA === 'true' || false,
        apiBaseUrl: import.meta.env.VITE_API_BASE_URL || 'https://api.yourdomain.com',
        environment: 'production',
        debug: false
      };
    
    case 'test':
      return {
        useMockData: true,
        apiBaseUrl: import.meta.env.VITE_API_BASE_URL || 'https://momantza.com/',
        environment: 'test',
        debug: true
      };
    
    default:
      return {
        useMockData: true,
        apiBaseUrl: 'https://momantza.com/',
        environment: 'development',
        debug: true
      };
  }
};

export const config = getEnvironmentConfig();

// Helper function to check if we should use mock data
export const shouldUseMockData = (): boolean => {
  return config.useMockData;
};

// Helper function to get API base URL
export const getApiBaseUrl = (): string => {
  return config.apiBaseUrl;
};

// Helper function to check if debug mode is enabled
export const isDebugMode = (): boolean => {
  return config.debug;
}; 