import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { CalendarIcon } from 'lucide-react';
import { format } from 'date-fns';
import { cn } from '@/lib/utils';
import { hallService, bookingService, authService } from '@/services/ServiceFactory';
import { useService, useServiceMutation } from '@/hooks/useService';
import { Booking } from '@/types';

interface AddBookingDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onBookingAdded: () => void;
}

export function AddBookingDialog({ isOpen, onClose, onBookingAdded }: AddBookingDialogProps) {
  const [formData, setFormData] = useState({
    customerName: '',
    customerPhone: '',
    customerEmail: '',
    eventType: '',
    eventDate: undefined as Date | undefined,
    timeSlot: '',
    guestCount: '',
    hallId: '',
    notes: ''
  });

  // Get current user using service hook
  const {
    data: currentUser,
    loading: userLoading,
    error: userError
  } = useService(() => Promise.resolve(authService.getCurrentUser()));

  // Get halls using service hook
  const {
    data: halls,
    loading: hallsLoading,
    error: hallsError
  } = useService(() => Promise.resolve(hallService.getAllHalls()));

  // Get available time slots using service hook
  const {
    data: timeSlots,
    loading: timeSlotsLoading,
    error: timeSlotsError,
    execute: executeTimeSlots
  } = useService(() => {
    if (formData.hallId && formData.eventDate) {
      return Promise.resolve(hallService.getAvailableTimeSlots(formData.hallId, formData.eventDate));
    }
    return Promise.resolve([]);
  }, {
    immediate: false
  });

  // Mutation hook for creating booking
  const createBookingMutation = useServiceMutation(
    (bookingData: Omit<Booking, 'id' | 'createdAt'>) => {
      if (!currentUser?.organizationId) {
        throw new Error('No organization found');
      }
      
      return bookingService.createBooking(bookingData);
    }
  );

  // Execute time slots fetch when hall and date are selected
  useEffect(() => {
    if (formData.hallId && formData.eventDate) {
      executeTimeSlots();
    }
  }, [formData.hallId, formData.eventDate, executeTimeSlots]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!formData.customerName || !formData.hallId || !formData.eventDate || !formData.timeSlot) {
      return;
    }

    try {
      await createBookingMutation.execute({
        customerName: formData.customerName,
        customerPhone: formData.customerPhone,
        customerEmail: formData.customerEmail,
        eventType: formData.eventType,
        eventDate: formData.eventDate?.toISOString() || '',
        timeSlot: formData.timeSlot as "morning" | "evening" | "fullday",
        guestCount: parseInt(formData.guestCount) || 0,
        hallId: formData.hallId,
        organizationId: currentUser?.organizationId || '',
        status: 'pending',
        totalAmount: 0
      });
      onBookingAdded();
      onClose();
      setFormData({
        customerName: '',
        customerPhone: '',
        customerEmail: '',
        eventType: '',
        eventDate: undefined,
        timeSlot: '',
        guestCount: '',
        hallId: '',
        notes: ''
      });
    } catch (error) {
      console.error('Failed to create booking:', error);
    }
  };

  const handleInputChange = (field: string, value: string | Date | undefined) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  // Loading state
  if (userLoading || hallsLoading) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Add New Booking</DialogTitle>
          </DialogHeader>
          <div className="animate-pulse space-y-4">
            <div className="h-8 bg-gray-200 rounded w-1/4"></div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {[...Array(6)].map((_, i) => (
                <div key={i} className="h-10 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  // Error state
  if (userError || hallsError || !currentUser || !halls) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Add New Booking</DialogTitle>
          </DialogHeader>
          <div className="text-center py-8">
            <p className="text-gray-500">Unable to load required data</p>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Add New Booking</DialogTitle>
        </DialogHeader>
        
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="customerName">Customer Name *</Label>
              <Input
                id="customerName"
                value={formData.customerName}
                onChange={(e) => handleInputChange('customerName', e.target.value)}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="customerPhone">Phone Number</Label>
              <Input
                id="customerPhone"
                value={formData.customerPhone}
                onChange={(e) => handleInputChange('customerPhone', e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="customerEmail">Email</Label>
              <Input
                id="customerEmail"
                type="email"
                value={formData.customerEmail}
                onChange={(e) => handleInputChange('customerEmail', e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="eventType">Event Type</Label>
              <Select value={formData.eventType} onValueChange={(value) => handleInputChange('eventType', value)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select event type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="wedding">Wedding</SelectItem>
                  <SelectItem value="reception">Reception</SelectItem>
                  <SelectItem value="birthday">Birthday</SelectItem>
                  <SelectItem value="corporate">Corporate Event</SelectItem>
                  <SelectItem value="other">Other</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="eventDate">Event Date *</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal",
                      !formData.eventDate && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {formData.eventDate ? format(formData.eventDate, "PPP") : "Pick a date"}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={formData.eventDate}
                    onSelect={(date) => handleInputChange('eventDate', date)}
                    disabled={(date) => date < new Date()}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div className="space-y-2">
              <Label htmlFor="hallId">Hall *</Label>
              <Select value={formData.hallId} onValueChange={(value) => handleInputChange('hallId', value)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select hall" />
                </SelectTrigger>
                <SelectContent>
                  {halls.map((hall) => (
                    <SelectItem key={hall.id} value={hall.id}>
                      {hall.name} - ₹{hall.rateCard.fullDayRate.toLocaleString()}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="timeSlot">Time Slot *</Label>
              <Select 
                value={formData.timeSlot} 
                onValueChange={(value) => handleInputChange('timeSlot', value)}
                disabled={!formData.hallId || !formData.eventDate || timeSlotsLoading}
              >
                <SelectTrigger>
                  <SelectValue placeholder={timeSlotsLoading ? "Loading..." : "Select time slot"} />
                </SelectTrigger>
                <SelectContent>
                  {timeSlots?.map((slot) => (
                    <SelectItem key={slot.value} value={slot.value}>
                      {slot.label} - ₹{slot.price.toLocaleString()}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="guestCount">Guest Count</Label>
              <Input
                id="guestCount"
                type="number"
                value={formData.guestCount}
                onChange={(e) => handleInputChange('guestCount', e.target.value)}
                min="1"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={(e) => handleInputChange('notes', e.target.value)}
              rows={3}
            />
          </div>

          <div className="flex justify-end space-x-2">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button 
              type="submit" 
              disabled={
                !formData.customerName || 
                !formData.hallId || 
                !formData.eventDate || 
                !formData.timeSlot ||
                createBookingMutation.loading
              }
            >
              {createBookingMutation.loading ? 'Creating...' : 'Create Booking'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}
